args.sql:
SELECT facetregistry, facetverts, facetfaces, facetresmm, geomdeltamm, 
       (facetfaces::numeric / (facetverts * facetresmm * facetresmm)) * 1000 as mcr
FROM scanmesh LIMIT 5;

